 function withhold(message,detail=''){setRunning(false);if(find('#mc-run'))find('#mc-run').disabled=true;if(find('#mc-annual-preview'))find('#mc-annual-preview').innerHTML='<p class="micro" data-i18n="simulation.t19">Path preview withheld until the inputs are valid.</p>';reserveHeight();finish();status('', 'unavailable');result=null;rawResult=null;exportContext=null;barFinals=[];find('#mc-summary-content').innerHTML='';find('#mc-output').innerHTML=`<div class="mc-empty-state error" role="status">${simulationErrorDescriptor(message)?simulationErrorMarkup(message):presentationMarkup(message)}</div>`;bindPresentation(find('#mc-audit'),'No current simulation result.');const errorDescriptor=simulationErrorDescriptor(detail);if(errorDescriptor)simMessage(find('#mc-error'),errorDescriptor.key,()=>simulationErrorDescriptor(detail).params);else bindPresentation(find('#mc-error'),detail);find('#mc-export').disabled=true;localizePresentation();publish('withheld',false);}
